#!/usr/bin/env bash
# Install every plugins/*/agents/*.md as a Codex custom agent in ~/.codex/agents/<name>.toml.
#
# Codex plugins can't ship agents, so this fills the gap. Skills don't need it: they come
# through `codex plugin marketplace add kaldren/agent-plugins`.
#
# Only overwrites files this script generated (they start with "# generated by agent-plugins").
# Re-run after `git pull` to pick up agent changes.
set -euo pipefail

repo="$(cd "$(dirname "$0")" && pwd)"
dest="${CODEX_HOME:-$HOME/.codex}/agents"
mkdir -p "$dest"
cd "$repo"

shopt -s nullglob
count=0
for rel in plugins/*/agents/*.md; do
  toml="$(python3 scripts/agent_md_to_toml.py "$rel" 2>&1)" || { echo "skip  $rel: $toml" >&2; continue; }
  name="$(basename "$rel" .md)"
  target="$dest/$name.toml"

  if [[ -e "$target" ]] && ! head -n1 "$target" | grep -q '^# generated by agent-plugins'; then
    echo "skip  $rel: $target exists and wasn't generated by this script" >&2
    continue
  fi

  printf '%s\n' "$toml" > "$target"
  echo "wrote $target"
  count=$((count + 1))
done

echo "$count agent(s) installed in $dest"
